#!/usr/bin/env bash

# Compiles the Common Lisp files the Lisp converter generated by loading every one of them with SBCL in one compilation unit after the runtime. Every file is in the package allbinary so
# the hand written runtime, the Lisp sources of the dependencies (META-INF/lisp/src of their jars),
# and this project are copied to one tree first. This project's sources are written to <output>/src.
# Arguments: source_dir output_dir object_dir dependency_dir runtime_dir compiler "flags" artifactId fail_on_error

set -uo pipefail

export PATH="/usr/local/bin:/usr/bin:/bin:$PATH"

source_dir="$(cygpath -u "$1")"
output_dir="$(cygpath -u "$2")"
object_dir="$(cygpath -u "$3")"
dependency_dir="$(cygpath -u "$4")"
runtime_dir="$(cygpath -u "$5")"
compiler="$(cygpath -u "$6")"
read -r -a compiler_flags <<< "$7"
artifact="$8"
fail_on_error="${9:-true}"

if [ ! -d "$source_dir" ]; then
    echo "No Lisp sources: $source_dir"
    exit 0
fi

rm -rf "$output_dir" "$object_dir"
tree="$object_dir/tree"
mkdir -p "$output_dir/src" "$tree"
cp -R "$source_dir/." "$output_dir/src/"
cp -R "$runtime_dir/." "$tree/"
if [ -d "$dependency_dir/src" ]; then
    cp -R "$dependency_dir/src/." "$tree/"
fi
cp -R "$source_dir/." "$tree/"

# A Windows program can not open a path over 260 characters, which a deep project folder plus a deep package reaches,
# so the check runs in a short temporary copy of the tree
short_tree="$(mktemp -d /tmp/lispXXXXXX)"
trap 'rm -rf "$short_tree"' EXIT
cp -R "$tree/." "$short_tree/"
cd "$short_tree" || exit 1
check="jcheck_$artifact.lisp"
count=0
{
    echo '(load "allbinary_java.lisp")'
    echo '(in-package :allbinary)'
    echo '(defvar *jwarnings* 0)'
    # The hand written java.* classes (warnings count)
    echo '(handler-bind ((warning (lambda (w) (incf *jwarnings*) (format t "WARNING: ~a~%" w) (muffle-warning w))))'
    echo '  (with-compilation-unit ()'
    find java -type f -name '*.lisp' 2>/dev/null | sort | while IFS= read -r file; do echo "    (load \"./$file\")"; done
    echo '))'
    # The dependencies: like Java a dependency is not checked again here since its own optional dependencies (TsUtil of
    # NoneOnlyJavaLibrary for LogJ2MEJavaLibrary) are not transitive so they are missing
    echo '(handler-bind ((warning (lambda (w) (muffle-warning w))))'
    echo '  (with-compilation-unit ()'
    ( cd "$source_dir" && find . -type f -name '*.lisp' | sed 's|^\./||' | sort ) > "$object_dir/project-files.txt"
    find . -type f -name '*.lisp' ! -name 'allbinary_java.lisp' ! -name 'jcheck_*' ! -path './java/*' | sed 's|^\./||' | sort | while IFS= read -r file; do
        grep -qxF "$file" "$object_dir/project-files.txt" || echo "    (load \"./$file\")"
    done
    echo '))'
    # This project (warnings count)
    echo '(handler-bind ((warning (lambda (w) (incf *jwarnings*) (format t "WARNING: ~a~%" w) (muffle-warning w))))'
    echo '  (with-compilation-unit ()'
    while IFS= read -r file; do echo "    (load \"./$file\")"; done < "$object_dir/project-files.txt"
    echo '))'
    echo "(format t \"Lisp warnings: ~a~%\" *jwarnings*)"
    echo '(sb-ext:exit :code (if (> *jwarnings* 0) 1 0))'
} > "$check"
count=$(find "$source_dir" -type f -name '*.lisp' | wc -l)
echo "Lisp files: $count"

output="$("$compiler" "${compiler_flags[@]}" "$check" 2>&1)"
status=$?
echo "$output"
if [ "$status" = "0" ]; then
    echo "Lisp compiled: $artifact"
    exit 0
fi
echo "Lisp build failed: $artifact" >&2
if [ "$fail_on_error" = "true" ]; then
    exit 1
fi
exit 0
